<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useSessionStore} from '../stores/session';import {useRunStore} from '../stores/run';import type {Target} from '@shared/labops-targets.js';import {t as tr} from '../i18n';import {useBusinessStore} from '../stores/business';import {useCollection} from '../composables/useCollection';import UiIcon from '../components/UiIcon.vue';import AsyncState from './AsyncState.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';
const props=defineProps<{section?:string}>(),emit=defineEmits<{navigate:[Target]}>(),session=useSessionStore(),run=useRunStore(),business=useBusinessStore(),query=ref(''),pins=useCollection('conversations',()=>business.profile?business.profile.identity+':'+business.profile.username:''),section=ref(props.section||'work'),busy=ref(false),error=ref(''),selected=ref<string|null>(null),title=ref('');
const list=computed(()=>(section.value==='chat'?session.chatConversations:session.workConversations).filter(c=>[c.title,c.preview||''].join(' ').toLowerCase().includes(query.value.toLowerCase())).slice().sort((a,b)=>Number(pins.ids.value.includes(b.id))-Number(pins.ids.value.includes(a.id))));watch(()=>props.section,v=>section.value=v||'work');onMounted(()=>session.loadConversations());useVisibleRefresh(()=>session.loadConversations(),()=>!run.inputLocked);
function create(){if(run.inputLocked)return;session.startDraft();emit('navigate',{view:'assistant',section:section.value});}
async function rename(){if(!selected.value)return;try{await session.renameConversation(selected.value,title.value);selected.value=null;}catch(e){error.value=(e as Error).message;}}
async function remove(){if(!selected.value||!confirm('删除此会话及其聊天显示，不撤销已提交的业务。继续？'))return;try{await session.removeConversation(selected.value);selected.value=null;}catch(e){error.value=(e as Error).message;}}
</script>
<template><label class="mobile-history-search"><UiIcon name="search"/><input v-model="query" type="search" :placeholder="tr('搜索会话')" :aria-label="tr('搜索会话')"></label><div class="mobile-segments" role="tablist" :aria-label="tr('会话分区')"><button role="tab" :aria-selected="section==='work'" @click="section='work';emit('navigate',{view:'sessions',section:'work'})">{{tr("工作会话")}} {{session.workConversations.length}}</button><button role="tab" :aria-selected="section==='chat'" @click="section='chat';emit('navigate',{view:'sessions',section:'chat'})">{{tr("聊天会话")}} {{session.chatConversations.length}}</button></div><button class="mobile-primary" :disabled="busy||run.inputLocked" @click="create">{{tr(section==='chat'?'新建聊天会话':'新建工作会话')}}</button><p v-if="error" role="alert">{{error}}</p><AsyncState :loading="session.listLoading" :error="session.listError||''" :empty="!list.length" :empty-text="tr('此分区暂无会话。')" @retry="session.loadConversations"><article v-for="c in list" :key="c.id" class="mobile-session-row"><button class="mobile-row" @click="emit('navigate',{view:'conversation',conversationId:c.id})"><b><UiIcon v-if="pins.ids.value.includes(c.id)" name="star" :size="12"/>{{c.title||tr('新会话')}}</b><span>{{c.preview||tr('尚未开始对话')}}</span><small>{{session.timeLabel(c.lastActivityAt)}} · {{c.messageCount}} {{tr("条消息")}}</small></button><button :aria-label="tr('管理会话')" @click="selected=c.id;title=c.title">{{tr("更多")}}</button></article></AsyncState><section v-if="selected" class="mobile-section"><h3>{{tr("管理会话")}}</h3><label>{{tr("会话名称")}}<input v-model="title" maxlength="120"></label><div class="mobile-actions"><button @click="pins.toggle(selected!)">{{tr(pins.ids.value.includes(selected!)?'取消置顶':'置顶会话')}}</button><button :disabled="busy" @click="rename">{{tr("保存名称")}}</button><button :disabled="busy||run.inputLocked" @click="remove">{{tr("删除会话")}}</button><button @click="selected=null">{{tr("取消")}}</button></div></section></template>
